    public static NativeBrainWeights Create(int seed)
    {
        var r = new System.Random(seed); int m1 = NativeCreatureModel.M1Width, h = NativeCreatureModel.M2Width;
        return new NativeBrainWeights {
            m1Input = Xavier(r, NativeCreatureModel.M1InputSize, m1), m1Residual = Xavier(r, m1, m1), m1Output = Xavier(r, m1, 4), m1Bias = new float[m1 * 2 + 4],
            m2Context = Xavier(r, NativeCreatureModel.M2ContextSize, h), m2Joint = Xavier(r, NativeCreatureModel.JointFeatureSize, h), m2Position = Xavier(r, NativeCreatureModel.PositionEncodingSize, h), m2AttentionQuery = Xavier(r, h, h), m2AttentionKey = Xavier(r, h, h), m2AttentionValue = Xavier(r, h, h), m2AttentionQuery2 = Xavier(r, h, h), m2AttentionKey2 = Xavier(r, h, h), m2AttentionValue2 = Xavier(r, h, h), m2Fusion = Xavier(r, h * 2, h), m2Residual = Xavier(r, h, h), m2Deep1 = Xavier(r, h, h), m2Output = Xavier(r, h, 1), m2StepEmbedding = Xavier(r, NativeCreatureModel.PlanningHorizon, h), m2Norm = Ones(h * 5), m2Bias = new float[h * 5 + 1]
