    internal static float[] Ones(int length){float[] a=new float[length];for(int i=0;i<length;i++)a[i]=1f;return a;}
    public NativeBrainWeights Clone(){var copy=new NativeBrainWeights{version=version};foreach(var f in typeof(NativeBrainWeights).GetFields().Where(f=>f.FieldType==typeof(float[]))){float[] value=(float[])f.GetValue(this);f.SetValue(copy,value==null?null:(float[])value.Clone());}return copy;}
    public void CopyFrom(NativeBrainWeights source) { var copy = source.Clone(); foreach (var f in typeof(NativeBrainWeights).GetFields()) f.SetValue(this, f.GetValue(copy)); }
