    public IEnumerable<KeyValuePair<string,float[]>> M2Parameters() { yield return P("context",m2Context); yield return P("joint",m2Joint); yield return P("position",m2Position); yield return P("attentionQuery",m2AttentionQuery); yield return P("attentionKey",m2AttentionKey); yield return P("attentionValue",m2AttentionValue); yield return P("attentionQuery2",m2AttentionQuery2); yield return P("attentionKey2",m2AttentionKey2); yield return P("attentionValue2",m2AttentionValue2); yield return P("fusion",m2Fusion); yield return P("residual",m2Residual); yield return P("deep1",m2Deep1); yield return P("output",m2Output); yield return P("stepEmbedding",m2StepEmbedding); yield return P("norm",m2Norm); yield return P("bias",m2Bias); }
