public sealed class NativeCreatureModel
{
    public const int M1Width=32,M2Width=128,M3Width=128,Hidden=M2Width,M2AttentionHeads=4,M3AttentionHeads=4,M2MlpHiddenLayers=3,M3MlpHiddenLayers=4,M2TransformerBlocks=2,M3TransformerBlocks=3,MaxLimbs=BodyMorphologyRules.MaxLimbs,MaxPathDepth=BodyMorphologyRules.MaxDepth,PlanningHorizon=5,ActionTicks=5,SequenceTicks=25,GoalWindowTicks=1000,M1GoalWindowTicks=25;
