    public NativePosePrediction LastPrediction { get; private set; }
    public int LeftLossSamples=>leftLosses.Count; public int RightLossSamples=>rightLosses.Count; public int M2LossSamples=>LeftLossSamples+RightLossSamples;
    public float LeftProposalLoss=>Mean(leftLosses); public float RightProposalLoss=>Mean(rightLosses); public bool LeftTrialComplete=>LeftLossSamples>=MinimumM2FitnessSamples; public bool RightTrialComplete=>RightLossSamples>=MinimumM2FitnessSamples; public bool IsBidirectionallyVerified=>LeftTrialComplete&&RightTrialComplete;
    public float BodyFitness=>BidirectionalFitness(LeftProposalLoss,LeftLossSamples,LeftTrialComplete,RightProposalLoss,RightLossSamples,RightTrialComplete);
    public int LatchedDirection { get; private set; } public float LeftBestTrialProgress { get; private set; } public float RightBestTrialProgress { get; private set; }
    private readonly Queue<float> leftLosses=new Queue<float>(), rightLosses=new Queue<float>(); private NativeDeterministicRng exploration; private int fixedGoalBlock=int.MinValue; private bool hasGoal,m1GoalAnchorInitialized; private Vector2 m1GoalAnchor,fixedGoalWorldHeading=Vector2.up;
    public NativeCreatureModel(NativeBrainWeights weights,int seed=0){Weights=weights??NativeBrainWeights.Create(seed==0?Environment.TickCount:seed);exploration=new NativeDeterministicRng((ulong)(seed==0?Environment.TickCount:seed));}

    public NativeObservation Observe(float[] global,Limb[] limbs,int tick,NativeLocalProprioception proprio,bool enableM1)
    {
        if(enableM1){if(!m1GoalAnchorInitialized){m1GoalAnchor=proprio.worldPosition;m1GoalAnchorInitialized=true;}RunM1(global,out Vector2 offset,out Vector2 heading);CurrentWorldGoal=new Vector2(Mathf.Clamp(m1GoalAnchor.x+SoftBiasedGoal(offset).x*GoalMagnitude,-WorldLayout.GoalHalfWidth,WorldLayout.GoalHalfWidth),m1GoalAnchor.y+SoftBiasedGoal(offset).y*GoalMagnitude);CurrentWorldGoalHeading=heading;GoalTicksRemaining=SequenceTicks;hasGoal=true;}
        else{m1GoalAnchorInitialized=false;int block=Mathf.Max(0,tick)/GoalWindowTicks;if(!hasGoal||block!=fixedGoalBlock){CurrentWorldGoal=new Vector2(Mathf.Clamp(proprio.worldPosition.x+FixedTrainingGoal(tick).x,-WorldLayout.GoalHalfWidth,WorldLayout.GoalHalfWidth),FixedGoalWorldHeight);fixedGoalWorldHeading=HeadingTowards(CurrentWorldGoal-proprio.worldPosition,proprio.worldRotationDegrees);fixedGoalBlock=block;hasGoal=true;}CurrentWorldGoalHeading=fixedGoalWorldHeading;GoalTicksRemaining=GoalWindowTicks-Mathf.Max(0,tick)%GoalWindowTicks;}
        Vector2 worldOffset=CurrentWorldGoal-proprio.worldPosition;CurrentGoal=proprio.WorldToTorsoVector(worldOffset);CurrentGoalHeading=RelativeHeading(CurrentWorldGoalHeading,proprio.worldRotationDegrees);LatchedDirection=ClassifyWorldGoalDirection(worldOffset.x);int count=Mathf.Min(limbs?.Length??0,MaxLimbs);
        var o=new NativeObservation{torsoWithGoal=TorsoFeatures(proprio,CurrentGoal,CurrentGoalHeading,true),torsoWithoutGoal=TorsoFeatures(proprio,Vector2.zero,Vector2.zero,false),jointFeatures=new float[MaxLimbs*JointFeatureSize],positionEncodings=new float[MaxLimbs*PositionEncodingSize],limbCount=count,goal=CurrentGoal,goalHeading=CurrentGoalHeading,worldGoal=CurrentWorldGoal,worldGoalHeading=CurrentWorldGoalHeading,startWorldPosition=proprio.worldPosition,startWorldRotationDegrees=proprio.worldRotationDegrees,tick=tick};
        for(int i=0;i<count;i++){Limb limb=limbs[i];Array.Copy(JointFeatures(limb.JointAngle,limb.JointSpeed,limb.TouchingEnvironment,limb.TouchingSelf,limb.TouchingOtherCreature),0,o.jointFeatures,i*JointFeatureSize,JointFeatureSize);Array.Copy(JointPositionEncoding(limb.genePath,limb.attachmentSlot),0,o.positionEncodings,i*PositionEncodingSize,PositionEncodingSize);}return o;
    }

    public NativeActionSequence OptimizeAndPlan(NativeObservation observation,NativeDynamicsWeights sharedM3,int sharedM3Samples)
    {
        var before=ForwardM2(observation,Weights);float bias=ActionBiasStrength(observation.tick);float[,] biased=ApplyActionBias(before.actions,observation,bias);var predicted=ForwardM3(observation,biased,sharedM3);float[] predictionGradient=new float[M3OutputSize];
        M2Loss(predicted.prediction,observation.goal,observation.goalHeading,biased,observation.limbCount,predictionGradient,out _,out _);float[,] actionGradient=BackwardM3(predicted,predictionGradient,null,sharedM3,null);AddEnergyGradient(actionGradient,biased,observation.limbCount);for(int s=0;s<5;s++)for(int l=0;l<observation.limbCount;l++)actionGradient[s,l]*=1f-bias;
        var gradient=Zero(Weights.M2Parameters());BackwardM2(before,actionGradient,Weights,gradient);ApplyAdam(Weights.M2Parameters(),gradient,M2Optimizer,M2LearningRate);
        var after=ForwardM2(observation,Weights);float[,] executed=ApplyActionBias(after.actions,observation,bias);float sigma=ExplorationSigma(sharedM3Samples);for(int s=0;s<5;s++)for(int l=0;l<observation.limbCount;l++)executed[s,l]=Mathf.Clamp(executed[s,l]+Gaussian()*sigma,-8f,8f);
        var finalPrediction=ForwardM3(observation,executed,sharedM3);LastM2Loss=M2Loss(finalPrediction.prediction,observation.goal,observation.goalHeading,executed,observation.limbCount,null,out float goalLoss,out float energyLoss);LastM2GoalLoss=goalLoss;LastM2EnergyLoss=energyLoss;LastPrediction=new NativePosePrediction((float[])finalPrediction.prediction.Clone());RecordFitness(LastM2Loss);
        return new NativeActionSequence(executed,observation.limbCount,observation.goal,observation.goalHeading,observation.worldGoal,observation.worldGoalHeading,LastPrediction,bias,sigma);
    }

    public static NativeM3BatchMetrics TrainSharedM3Batch(IReadOnlyList<NativeCompletedSequence> source,NativeDynamicsWeights weights,NativeOptimizerState optimizer)
    {var samples=(source??Array.Empty<NativeCompletedSequence>()).Where(s=>s?.observation!=null).OrderBy(s=>s.sampleId??string.Empty,StringComparer.Ordinal).ThenBy(s=>s.observation.tick).ToList();var metrics=new NativeM3BatchMetrics{sampleCount=samples.Count};if(samples.Count==0)return metrics;var gradients=Zero(weights.Parameters());foreach(var sample in samples){var cache=ForwardM3(sample.observation,sample.ActionMatrix(),weights);float[] pg=new float[M3OutputSize],ag=new float[M3AuxiliaryOutputSize];float pose=M3Loss(cache.prediction,sample.actualPoses,pg,out float mse,out float relative),aux=M3AuxiliaryLoss(cache.auxiliary,sample.actualAuxiliary,ag,out float velocity,out float contact);BackwardM3(cache,pg,ag,weights,gradients);metrics.loss+=pose+aux;metrics.poseMse+=mse;metrics.relativeLoss+=relative;metrics.velocityLoss+=velocity;metrics.contactLoss+=contact;}foreach(float[] values in gradients.Values)for(int i=0;i<values.Length;i++)values[i]/=samples.Count;ApplyAdam(weights.Parameters(),gradients,optimizer,M3LearningRate);metrics.loss/=samples.Count;metrics.poseMse/=samples.Count;metrics.relativeLoss/=samples.Count;metrics.velocityLoss/=samples.Count;metrics.contactLoss/=samples.Count;metrics.optimizerSteps=optimizer.step;return metrics;}

    public static float[] PredictM3ForTesting(NativeObservation observation,float[,] actions,NativeDynamicsWeights weights)=>(float[])ForwardM3(observation,actions,weights).prediction.Clone();
    public static float[] PredictM3AuxiliaryForTesting(NativeObservation observation,float[,] actions,NativeDynamicsWeights weights)=>(float[])ForwardM3(observation,actions,weights).auxiliary.Clone();
    public static float[] M3GradientForTesting(NativeCompletedSequence sample,NativeDynamicsWeights weights,string parameterName){var cache=ForwardM3(sample.observation,sample.ActionMatrix(),weights);float[] pg=new float[M3OutputSize],ag=new float[M3AuxiliaryOutputSize];M3Loss(cache.prediction,sample.actualPoses,pg,out _,out _);M3AuxiliaryLoss(cache.auxiliary,sample.actualAuxiliary,ag,out _,out _);var gradients=Zero(weights.Parameters());BackwardM3(cache,pg,ag,weights,gradients);return gradients[parameterName];}
    public static float M3LossForTesting(NativeCompletedSequence sample,NativeDynamicsWeights weights){var cache=ForwardM3(sample.observation,sample.ActionMatrix(),weights);return M3Loss(cache.prediction,sample.actualPoses,null,out _,out _)+M3AuxiliaryLoss(cache.auxiliary,sample.actualAuxiliary,null,out _,out _);}
    public static float[] M2GradientForTesting(NativeObservation observation,NativeBrainWeights m2,NativeDynamicsWeights m3,string parameterName){var cache=ForwardM2(observation,m2);float bias=ActionBiasStrength(observation.tick);float[,] actions=ApplyActionBias(cache.actions,observation,bias);var prediction=ForwardM3(observation,actions,m3);float[] pg=new float[M3OutputSize];M2Loss(prediction.prediction,observation.goal,observation.goalHeading,actions,observation.limbCount,pg,out _,out _);float[,] ag=BackwardM3(prediction,pg,null,m3,null);AddEnergyGradient(ag,actions,observation.limbCount);for(int s=0;s<5;s++)for(int l=0;l<observation.limbCount;l++)ag[s,l]*=1f-bias;var gradients=Zero(m2.M2Parameters());BackwardM2(cache,ag,m2,gradients);return gradients[parameterName];}
    public static float M2LossForTesting(NativeObservation observation,NativeBrainWeights m2,NativeDynamicsWeights m3){var cache=ForwardM2(observation,m2);float[,] actions=ApplyActionBias(cache.actions,observation,ActionBiasStrength(observation.tick));var prediction=ForwardM3(observation,actions,m3);return M2Loss(prediction.prediction,observation.goal,observation.goalHeading,actions,observation.limbCount,null,out _,out _);}

    public static float M3Loss(float[] predicted,float[] actual,float[] gradient,out float mse,out float relative)
    {mse=0f;relative=0f;if(gradient!=null)Array.Clear(gradient,0,gradient.Length);for(int s=0;s<PlanningHorizon;s++){int i=s*PoseValueCount;for(int c=0;c<2;c++){float e=predicted[i+c]-actual[i+c];mse+=e*e/(PlanningHorizon*2f);if(gradient!=null)gradient[i+c]+=e/PlanningHorizon;}for(int c=2;c<4;c++){float e=predicted[i+c]-actual[i+c];mse+=M3HeadingLossWeight*e*e/(PlanningHorizon*2f);if(gradient!=null)gradient[i+c]+=M3HeadingLossWeight*e/PlanningHorizon;}float tx=actual[i],ty=actual[i+1],d=tx*tx+ty*ty;if(d<=MotionThreshold*MotionThreshold)continue;float x=predicted[i]-tx,y=predicted[i+1]-ty,den=d+MotionThreshold*MotionThreshold;relative+=AntiZeroWeight*(x*x+y*y)/(den*PlanningHorizon);if(gradient!=null){gradient[i]+=2f*AntiZeroWeight*x/(den*PlanningHorizon);gradient[i+1]+=2f*AntiZeroWeight*y/(den*PlanningHorizon);}}return mse+relative;}
    public static float M3AuxiliaryLoss(float[] predicted,float[] actual,float[] gradient,out float velocityLoss,out float contactLoss){velocityLoss=0f;contactLoss=0f;actual=actual??new float[M3AuxiliaryOutputSize];if(gradient!=null)Array.Clear(gradient,0,gradient.Length);for(int s=0;s<PlanningHorizon;s++){int i=s*AuxiliaryValueCount;for(int c=0;c<2;c++){float e=predicted[i+c]-actual[i+c];velocityLoss+=M3VelocityLossWeight*e*e/(PlanningHorizon*2f);if(gradient!=null)gradient[i+c]=M3VelocityLossWeight*e/PlanningHorizon;}for(int c=2;c<5;c++){float p=Mathf.Clamp(predicted[i+c],1e-5f,1f-1e-5f),target=Mathf.Clamp01(actual[i+c]);contactLoss-=M3ContactLossWeight*(target*Mathf.Log(p)+(1f-target)*Mathf.Log(1f-p))/(PlanningHorizon*3f);if(gradient!=null)gradient[i+c]=M3ContactLossWeight*(p-target)/(p*(1f-p)*PlanningHorizon*3f);}}return velocityLoss+contactLoss;}
    public static float M2GoalLoss(float[] predicted,Vector2 goal,Vector2 heading){float total=GoalStepWeights.Sum(),loss=0f;for(int s=0;s<PlanningHorizon;s++){int i=s*PoseValueCount;float x=predicted[i]-goal.x,y=predicted[i+1]-goal.y,hs=predicted[i+2]-heading.x,hc=predicted[i+3]-heading.y;loss+=GoalStepWeights[s]*(x*x+y*y+M2HeadingLossWeight*(hs*hs+hc*hc))/total;}return loss;}
    private static float M2Loss(float[] predicted,Vector2 goal,Vector2 heading,float[,] actions,int activeLimbs,float[] gradient,out float goalLoss,out float energyLoss){float total=GoalStepWeights.Sum();goalLoss=0f;if(gradient!=null)Array.Clear(gradient,0,gradient.Length);for(int s=0;s<PlanningHorizon;s++){int i=s*PoseValueCount;float x=predicted[i]-goal.x,y=predicted[i+1]-goal.y,hs=predicted[i+2]-heading.x,hc=predicted[i+3]-heading.y,k=GoalStepWeights[s]/total;goalLoss+=k*(x*x+y*y+M2HeadingLossWeight*(hs*hs+hc*hc));if(gradient!=null){gradient[i]=2f*k*x;gradient[i+1]=2f*k*y;gradient[i+2]=2f*k*M2HeadingLossWeight*hs;gradient[i+3]=2f*k*M2HeadingLossWeight*hc;}}int limbs=Mathf.Clamp(activeLimbs,0,actions.GetLength(1)),count=Mathf.Max(1,actions.GetLength(0)*limbs);energyLoss=0f;for(int s=0;s<actions.GetLength(0);s++)for(int l=0;l<limbs;l++){float n=actions[s,l]/8f;energyLoss+=ActionEnergyWeight*n*n/count;}return goalLoss+energyLoss;}
    private static void AddEnergyGradient(float[,] g,float[,] a,int activeLimbs){int limbs=Mathf.Clamp(activeLimbs,0,a.GetLength(1)),count=Mathf.Max(1,a.GetLength(0)*limbs);for(int s=0;s<a.GetLength(0);s++)for(int l=0;l<limbs;l++)g[s,l]+=2f*ActionEnergyWeight*a[s,l]/(64f*count);}

    public static float ActionBiasStrength(int tick){if(tick>=ActionBiasEndTick)return 0f;double p=Math.Max(0d,Math.Min(1d,tick/(double)ActionBiasEndTick));return Math.Max(1e-6f,(float)(.25d*(1d+Math.Cos(Math.PI*p))));}
    public static float ExplorationSigma(int updates){float p=Mathf.Clamp01(updates/(float)ExplorationDecayUpdates);return p>=1f?ExplorationFloorSigma:ExplorationStartSigma*Mathf.Pow(ExplorationFloorSigma/ExplorationStartSigma,p);}
    public static float BiasAction(float action,float strength,int parity,int step){if(strength<=0f)return Mathf.Clamp(action,-8f,8f);float sign=Mathf.Abs(action)>1e-7f?Mathf.Sign(action):(((parity+step)&1)==0?1f:-1f);return Mathf.Clamp(sign*Mathf.Lerp(Mathf.Abs(action),.75f,strength),-8f,8f);}
    private static float[,] ApplyActionBias(float[,] raw,NativeObservation o,float strength){var result=new float[5,MaxLimbs];for(int s=0;s<5;s++)for(int l=0;l<o.limbCount;l++){int parity=0;for(int i=0;i<PositionEncodingSize;i++)parity^=Mathf.RoundToInt((o.positionEncodings[l*PositionEncodingSize+i]+1f)*(i+3));result[s,l]=BiasAction(raw[s,l],strength,parity,s);}return result;}
    public static float[] JointFeatures(float angleDegrees,float speed,bool environment=false,bool self=false,bool other=false){float a=angleDegrees*Mathf.Deg2Rad,w=Mathf.Clamp(speed/720f,-1f,1f);return new[]{Mathf.Sin(a),Mathf.Cos(a),w*Mathf.Cos(a),-w*Mathf.Sin(a),environment?1f:0f,self?1f:0f,other?1f:0f};}
    public static float[] JointPositionEncoding(int[] path,int slot){float[] result=new float[PositionEncodingSize];int depth=Mathf.Clamp(path?.Length??0,0,MaxPathDepth);if(depth==0){path=new[]{slot};depth=1;}for(int d=0;d<depth;d++){float phase=2f*Mathf.PI*Mathf.Repeat(path[d],8)/8f;int i=d*5;result[i]=1f;result[i+1]=Mathf.Sin(phase);result[i+2]=Mathf.Cos(phase);result[i+3]=Mathf.Sin(2f*phase);result[i+4]=Mathf.Cos(2f*phase);}result[15]=depth/(float)MaxPathDepth;return result;}
    public const float FixedGoalWorldHeight=WorldLayout.GroundTop+.5f;
    public static Vector2 FixedTrainingGoal(int tick)=>new Vector2(((Mathf.Max(0,tick)/GoalWindowTicks)&1)==0?CurriculumGoalMagnitude:-CurriculumGoalMagnitude,0f);
    public static bool CanPlaceFixedTrainingGoal(Vector2 torsoPosition,int tick)=>Mathf.Abs(torsoPosition.x+FixedTrainingGoal(tick).x)<=WorldLayout.GoalHalfWidth;
    public static int ClassifyWorldGoalDirection(float x)=>x<-.15f?-1:x>.15f?1:0;
    public static float BidirectionalFitness(float left,int ln,bool lc,float right,int rn,bool rc)=>ln<MinimumM2FitnessSamples||rn<MinimumM2FitnessSamples||!lc||!rc||!IsFinite(left)||!IsFinite(right)?float.PositiveInfinity:Mathf.Max(left,right);
    public static bool IsFinite(float value)=>!float.IsNaN(value)&&!float.IsInfinity(value);

    private void RecordFitness(float loss){if(!IsFinite(loss)||LatchedDirection==0)return;var q=LatchedDirection<0?leftLosses:rightLosses;q.Enqueue(loss);while(q.Count>M2FitnessWindow)q.Dequeue();}
    public void RecordMeasuredProgress(Vector2 d){if(LatchedDirection<0)LeftBestTrialProgress=Mathf.Max(LeftBestTrialProgress,-d.x);else if(LatchedDirection>0)RightBestTrialProgress=Mathf.Max(RightBestTrialProgress,d.x);}
    public void RepairFrom(NativeBrainWeights source){Weights.CopyFrom(source);M2Optimizer=new NativeOptimizerState();}
    public void RelatchFixedTrainingGoal(){fixedGoalBlock=int.MinValue;hasGoal=false;}
    public NativeCreatureSave Capture()=>new NativeCreatureSave{weights=Weights,m2Optimizer=M2Optimizer,goalX=CurrentGoal.x,goalY=CurrentGoal.y,goalHeadingSin=CurrentGoalHeading.x,goalHeadingCos=CurrentGoalHeading.y,worldGoalX=CurrentWorldGoal.x,worldGoalY=CurrentWorldGoal.y,worldGoalHeadingSin=CurrentWorldGoalHeading.x,worldGoalHeadingCos=CurrentWorldGoalHeading.y,fixedGoalHeadingSin=fixedGoalWorldHeading.x,fixedGoalHeadingCos=fixedGoalWorldHeading.y,goalTicksRemaining=GoalTicksRemaining,fixedGoalBlock=fixedGoalBlock,m1AnchorX=m1GoalAnchor.x,m1AnchorY=m1GoalAnchor.y,m1AnchorInitialized=m1GoalAnchorInitialized,explorationState=exploration.State,leftLosses=leftLosses.ToList(),rightLosses=rightLosses.ToList(),leftBestProgress=LeftBestTrialProgress,rightBestProgress=RightBestTrialProgress};
    public void Restore(NativeCreatureSave save){if(save==null)return;M2Optimizer=save.m2Optimizer??new NativeOptimizerState();CurrentGoal=new Vector2(save.goalX,save.goalY);CurrentGoalHeading=NormalizeHeading(new Vector2(save.goalHeadingSin,save.goalHeadingCos),Vector2.up);CurrentWorldGoal=new Vector2(save.worldGoalX,save.worldGoalY);CurrentWorldGoalHeading=NormalizeHeading(new Vector2(save.worldGoalHeadingSin,save.worldGoalHeadingCos),Vector2.up);fixedGoalWorldHeading=NormalizeHeading(new Vector2(save.fixedGoalHeadingSin,save.fixedGoalHeadingCos),CurrentWorldGoalHeading);GoalTicksRemaining=save.goalTicksRemaining;fixedGoalBlock=save.fixedGoalBlock;m1GoalAnchor=new Vector2(save.m1AnchorX,save.m1AnchorY);m1GoalAnchorInitialized=save.m1AnchorInitialized;hasGoal=true;exploration.State=save.explorationState;leftLosses.Clear();rightLosses.Clear();foreach(float v in (save.leftLosses??new List<float>()).TakeLast(M2FitnessWindow))leftLosses.Enqueue(v);foreach(float v in (save.rightLosses??new List<float>()).TakeLast(M2FitnessWindow))rightLosses.Enqueue(v);LeftBestTrialProgress=save.leftBestProgress;RightBestTrialProgress=save.rightBestProgress;}

    private void RunM1(float[] input,out Vector2 goalOffset,out Vector2 heading){var a=ForwardDense(input,Weights.m1Input,Weights.m1Bias,0,M1InputSize,M1Width,true).output;var b=ForwardDense(a,Weights.m1Residual,Weights.m1Bias,M1Width,M1Width,M1Width,true).output;for(int i=0;i<M1Width;i++)a[i]=(float)Math.Tanh(a[i]+b[i]);var o=ForwardDense(a,Weights.m1Output,Weights.m1Bias,M1Width*2,M1Width,4,false).output;goalOffset=new Vector2((float)Math.Tanh(o[0]),(float)Math.Tanh(o[1]));heading=NormalizeHeading(new Vector2((float)Math.Tanh(o[2]),(float)Math.Tanh(o[3])),Vector2.up);}
    private static Vector2 SoftBiasedGoal(Vector2 raw){float m=Mathf.Clamp01(raw.magnitude);Vector2 d=m>.0001f?raw/m:Vector2.right;return d*(.35f+.65f*m);}
    public static Vector2 HeadingEncoding(float degrees){float radians=degrees*Mathf.Deg2Rad;return new Vector2(Mathf.Sin(radians),Mathf.Cos(radians));}
    public static Vector2 NormalizeHeading(Vector2 heading,Vector2 fallback){if(heading.sqrMagnitude>1e-8f)return heading.normalized;return fallback.sqrMagnitude>1e-8f?fallback.normalized:Vector2.up;}
    public static Vector2 HeadingTowards(Vector2 direction,float fallbackDegrees){return direction.sqrMagnitude>1e-8f?HeadingEncoding(Mathf.Atan2(direction.y,direction.x)*Mathf.Rad2Deg):HeadingEncoding(fallbackDegrees);}
    public static Vector2 RelativeHeading(Vector2 worldHeading,float sequenceStartRotationDegrees){float headingDegrees=Mathf.Atan2(worldHeading.x,worldHeading.y)*Mathf.Rad2Deg;return HeadingEncoding(headingDegrees-sequenceStartRotationDegrees);}
    private static float[] TorsoFeatures(NativeLocalProprioception p,Vector2 goal,Vector2 goalHeading,bool includeGoal){float a=p.worldRotationDegrees*Mathf.Deg2Rad;return includeGoal?new[]{p.worldPosition.x/WorldLayout.WorldHalfWidth,p.worldPosition.y/WorldLayout.SpawnRowSpacing,p.localLinearVelocity.x,p.localLinearVelocity.y,Mathf.Sin(a),Mathf.Cos(a),goal.x,goal.y,goalHeading.x,goalHeading.y}:new[]{p.worldPosition.x/WorldLayout.WorldHalfWidth,p.worldPosition.y/WorldLayout.SpawnRowSpacing,p.localLinearVelocity.x,p.localLinearVelocity.y,Mathf.Sin(a),Mathf.Cos(a)};}
    private float Gaussian(){float a=Mathf.Max(1e-7f,exploration.NextFloat()),b=exploration.NextFloat();return Mathf.Sqrt(-2f*Mathf.Log(a))*Mathf.Cos(2f*Mathf.PI*b);}
    private static float Mean(IEnumerable<float> values){int n=0;float sum=0f;foreach(float v in values){sum+=v;n++;}return n==0?float.PositiveInfinity:sum/n;}

    private static M2Cache ForwardM2(NativeObservation o,NativeBrainWeights w)
    {
        var c=new M2Cache{observation=o,context=ForwardDense(o.torsoWithGoal,w.m2Context,w.m2Bias,0,M2ContextSize,Hidden,true),limbs=new JointCache[o.limbCount],actions=new float[5,MaxLimbs]};float[][] tokens=new float[o.limbCount][];
        for(int l=0;l<o.limbCount;l++){c.limbs[l]=ForwardJoint(Slice(o.jointFeatures,l*JointFeatureSize,JointFeatureSize),Slice(o.positionEncodings,l*PositionEncodingSize,PositionEncodingSize),w.m2Joint,w.m2Position,w.m2Bias,Hidden);tokens[l]=c.limbs[l].output;}
        c.attention=ForwardAttention(tokens,w.m2AttentionQuery,w.m2AttentionKey,w.m2AttentionValue,w.m2Norm,0,M2AttentionHeads);c.attention2=ForwardAttention(c.attention.output,w.m2AttentionQuery2,w.m2AttentionKey2,w.m2AttentionValue2,w.m2Norm,Hidden,M2AttentionHeads);c.heads=new MlpCache[o.limbCount];c.steps=new StepDecoderCache[o.limbCount][];
        for(int l=0;l<o.limbCount;l++){c.heads[l]=ForwardMlp(Concat(c.attention2.output[l],c.context.output),w.m2Fusion,w.m2Residual,new[]{w.m2Deep1},w.m2Bias,w.m2Norm,Hidden*2);c.steps[l]=new StepDecoderCache[PlanningHorizon];for(int s=0;s<PlanningHorizon;s++){float[] input=new float[Hidden];for(int h=0;h<Hidden;h++)input[h]=c.heads[l].output[h]+w.m2StepEmbedding[s*Hidden+h];var norm=ForwardRms(input,w.m2Norm,Hidden*4);var layer=ForwardDense(norm.output,w.m2Output,w.m2Bias,Hidden*5,Hidden,1,false);float value=(float)Math.Tanh(layer.pre[0])*MaximumActionDegrees;c.steps[l][s]=new StepDecoderCache{step=s,input=input,norm=norm,layer=layer,output=value};c.actions[s,l]=value;}}return c;
    }
    private static void BackwardM2(M2Cache c,float[,] actionGradient,NativeBrainWeights w,Dictionary<string,float[]> g)
    {
        float[][] attentionGradient=Enumerable.Range(0,c.observation.limbCount).Select(_=>new float[Hidden]).ToArray();float[] contextGradient=new float[Hidden];
        for(int l=0;l<c.observation.limbCount;l++){float[] hiddenGradient=new float[Hidden];for(int s=0;s<PlanningHorizon;s++){var step=c.steps[l][s];float t=step.output/MaximumActionDegrees;float[] raw={actionGradient[s,l]*MaximumActionDegrees*(1f-t*t)};float[] normalizedGradient=BackwardDense(step.layer,raw,w.m2Output,g["output"],g["bias"]);float[] ig=BackwardRms(step.norm,normalizedGradient,g["norm"]);for(int h=0;h<Hidden;h++){hiddenGradient[h]+=ig[h];g["stepEmbedding"][s*Hidden+h]+=ig[h];}}float[] fg=BackwardMlp(c.heads[l],hiddenGradient,w.m2Fusion,w.m2Residual,new[]{w.m2Deep1},g["fusion"],g["residual"],new[]{g["deep1"]},g["bias"],g["norm"]);Array.Copy(fg,attentionGradient[l],Hidden);for(int h=0;h<Hidden;h++)contextGradient[h]+=fg[Hidden+h];}
        float[][] firstBlockGradient=BackwardAttention(c.attention2,attentionGradient,w.m2AttentionQuery2,w.m2AttentionKey2,w.m2AttentionValue2,g["attentionQuery2"],g["attentionKey2"],g["attentionValue2"],g["norm"]);float[][] tg=BackwardAttention(c.attention,firstBlockGradient,w.m2AttentionQuery,w.m2AttentionKey,w.m2AttentionValue,g["attentionQuery"],g["attentionKey"],g["attentionValue"],g["norm"]);for(int l=0;l<c.observation.limbCount;l++)BackwardJoint(c.limbs[l],tg[l],w.m2Joint,w.m2Position,g["joint"],g["position"],g["bias"],Hidden);BackwardDense(c.context,contextGradient,w.m2Context,g["context"],g["bias"]);
    }
    private static M3Cache ForwardM3(NativeObservation o,float[,] actions,NativeDynamicsWeights w)
    {
        var c=new M3Cache{observation=o,actions=actions,context=ForwardDense(o.torsoWithoutGoal,w.context,w.bias,0,M3ContextSize,Hidden,true),limbs=new JointCache[o.limbCount]};float[][] tokens=new float[o.limbCount][];
        for(int l=0;l<o.limbCount;l++){float[] input=new float[M3JointInputSize];Array.Copy(o.jointFeatures,l*JointFeatureSize,input,0,JointFeatureSize);for(int s=0;s<PlanningHorizon;s++)input[JointFeatureSize+s]=actions[s,l]/MaximumActionDegrees;c.limbs[l]=ForwardJoint(input,Slice(o.positionEncodings,l*PositionEncodingSize,PositionEncodingSize),w.joint,w.position,w.bias,Hidden);tokens[l]=c.limbs[l].output;}
        c.attention=ForwardAttention(tokens,w.attentionQuery,w.attentionKey,w.attentionValue,w.norm,0,M3AttentionHeads);c.attention2=ForwardAttention(c.attention.output,w.attentionQuery2,w.attentionKey2,w.attentionValue2,w.norm,Hidden,M3AttentionHeads);c.attention3=ForwardAttention(c.attention2.output,w.attentionQuery3,w.attentionKey3,w.attentionValue3,w.norm,Hidden*2,M3AttentionHeads);
        float[][] queries=new float[PlanningHorizon][];for(int s=0;s<PlanningHorizon;s++){queries[s]=new float[Hidden];for(int h=0;h<Hidden;h++)queries[s][h]=c.context.output[h]+w.horizonQueries[s*Hidden+h];}c.cross=ForwardCrossAttention(queries,c.attention3.output,w.crossQuery,w.crossKey,w.crossValue,w.norm,Hidden*3,Hidden*4,M3AttentionHeads);c.heads=new MlpCache[PlanningHorizon];c.outputLayers=new DenseCache[PlanningHorizon];c.rawOutputs=new float[PlanningHorizon][];c.prediction=new float[M3OutputSize];c.auxiliary=new float[M3AuxiliaryOutputSize];
        for(int s=0;s<PlanningHorizon;s++){c.heads[s]=ForwardMlp(Concat(c.cross.output[s],c.context.output),w.fusion,w.residual,new[]{w.deep1,w.deep2},w.bias,w.norm,Hidden*5);c.outputLayers[s]=ForwardDense(c.heads[s].output,w.output,w.bias,Hidden*6,Hidden,M3ValuesPerHorizon,false);c.rawOutputs[s]=new float[M3ValuesPerHorizon];for(int j=0;j<6;j++)c.rawOutputs[s][j]=(float)Math.Tanh(c.outputLayers[s].pre[j]);for(int j=6;j<M3ValuesPerHorizon;j++)c.rawOutputs[s][j]=Sigmoid(c.outputLayers[s].pre[j]);for(int j=0;j<PoseValueCount;j++)c.prediction[s*PoseValueCount+j]=c.rawOutputs[s][j];for(int j=0;j<AuxiliaryValueCount;j++)c.auxiliary[s*AuxiliaryValueCount+j]=c.rawOutputs[s][PoseValueCount+j];}return c;
    }
    private static float[,] BackwardM3(M3Cache c,float[] poseGradient,float[] auxiliaryGradient,NativeDynamicsWeights w,Dictionary<string,float[]> supplied)
    {
        var g=supplied;float[][] crossGradient=Enumerable.Range(0,PlanningHorizon).Select(_=>new float[Hidden]).ToArray();float[] contextGradient=new float[Hidden];
        for(int s=0;s<PlanningHorizon;s++){float[] og=new float[M3ValuesPerHorizon];for(int j=0;j<PoseValueCount;j++)og[j]=(poseGradient?[s*PoseValueCount+j]).GetValueOrDefault();for(int j=0;j<AuxiliaryValueCount;j++)og[PoseValueCount+j]=(auxiliaryGradient?[s*AuxiliaryValueCount+j]).GetValueOrDefault();for(int j=0;j<6;j++)og[j]*=1f-c.rawOutputs[s][j]*c.rawOutputs[s][j];for(int j=6;j<M3ValuesPerHorizon;j++)og[j]*=c.rawOutputs[s][j]*(1f-c.rawOutputs[s][j]);float[] hidden=BackwardDense(c.outputLayers[s],og,w.output,G(g,"output"),G(g,"bias"));float[] fg=BackwardMlp(c.heads[s],hidden,w.fusion,w.residual,new[]{w.deep1,w.deep2},G(g,"fusion"),G(g,"residual"),new[]{G(g,"deep1"),G(g,"deep2")},G(g,"bias"),G(g,"norm"));Array.Copy(fg,crossGradient[s],Hidden);for(int h=0;h<Hidden;h++)contextGradient[h]+=fg[Hidden+h];}
        CrossBackward cb=BackwardCrossAttention(c.cross,crossGradient,w.crossQuery,w.crossKey,w.crossValue,G(g,"crossQuery"),G(g,"crossKey"),G(g,"crossValue"),G(g,"norm"));for(int s=0;s<PlanningHorizon;s++)for(int h=0;h<Hidden;h++){contextGradient[h]+=cb.queryGradient[s][h];if(g!=null)g["horizonQueries"][s*Hidden+h]+=cb.queryGradient[s][h];}
        float[][] secondBlockGradient=BackwardAttention(c.attention3,cb.tokenGradient,w.attentionQuery3,w.attentionKey3,w.attentionValue3,G(g,"attentionQuery3"),G(g,"attentionKey3"),G(g,"attentionValue3"),G(g,"norm"));float[][] firstBlockGradient=BackwardAttention(c.attention2,secondBlockGradient,w.attentionQuery2,w.attentionKey2,w.attentionValue2,G(g,"attentionQuery2"),G(g,"attentionKey2"),G(g,"attentionValue2"),G(g,"norm"));float[][] tg=BackwardAttention(c.attention,firstBlockGradient,w.attentionQuery,w.attentionKey,w.attentionValue,G(g,"attentionQuery"),G(g,"attentionKey"),G(g,"attentionValue"),G(g,"norm"));float[,] result=new float[5,MaxLimbs];for(int l=0;l<c.observation.limbCount;l++){float[] ig=BackwardJoint(c.limbs[l],tg[l],w.joint,w.position,G(g,"joint"),G(g,"position"),G(g,"bias"),Hidden);for(int s=0;s<5;s++)result[s,l]=ig[JointFeatureSize+s]/MaximumActionDegrees;}BackwardDense(c.context,contextGradient,w.context,G(g,"context"),G(g,"bias"));return result;
    }

    private static JointCache ForwardJoint(float[] input,float[] position,float[] iw,float[] pw,float[] bias,int offset){var c=new JointCache{input=input,position=position,pre=new float[Hidden],output=new float[Hidden]};for(int h=0;h<Hidden;h++){float v=bias[offset+h];for(int i=0;i<input.Length;i++)v+=input[i]*iw[i*Hidden+h];for(int i=0;i<position.Length;i++)v+=position[i]*pw[i*Hidden+h];c.pre[h]=v;c.output[h]=SiLU(v);}return c;}
    private static float[] BackwardJoint(JointCache c,float[] og,float[] iw,float[] pw,float[] iwg,float[] pwg,float[] bg,int offset){float[] ig=new float[c.input.Length];for(int h=0;h<Hidden;h++){float g=og[h]*SiLUDerivative(c.pre[h]);if(bg!=null)bg[offset+h]+=g;for(int i=0;i<c.input.Length;i++){if(iwg!=null)iwg[i*Hidden+h]+=c.input[i]*g;ig[i]+=iw[i*Hidden+h]*g;}for(int i=0;i<c.position.Length;i++)if(pwg!=null)pwg[i*Hidden+h]+=c.position[i]*g;}return ig;}
    private static AttentionCache ForwardAttention(float[][] input,float[] qw,float[] kw,float[] vw,float[] gamma,int gammaOffset,int heads)
    {
        int n=input.Length;var c=new AttentionCache{input=input,normalized=new RmsCache[n],q=new float[n][],k=new float[n][],v=new float[n][],output=new float[n][],probability=new float[heads,n,n],heads=heads};for(int i=0;i<n;i++){c.normalized[i]=ForwardRms(input[i],gamma,gammaOffset);c.q[i]=Linear(c.normalized[i].output,qw);c.k[i]=Linear(c.normalized[i].output,kw);c.v[i]=Linear(c.normalized[i].output,vw);c.output[i]=(float[])input[i].Clone();}
        for(int head=0;head<heads;head++){int start=AttentionHeadStart(head,heads),headWidth=AttentionHeadWidth(head,heads);float scale=1f/Mathf.Sqrt(headWidth);float[] scores=new float[n];for(int i=0;i<n;i++){float max=float.NegativeInfinity,sum=0f;for(int j=0;j<n;j++){float dot=0f;for(int h=0;h<headWidth;h++)dot+=c.q[i][start+h]*c.k[j][start+h];scores[j]=dot*scale;max=Mathf.Max(max,scores[j]);}for(int j=0;j<n;j++){c.probability[head,i,j]=Mathf.Exp(Mathf.Clamp(scores[j]-max,-20f,20f));sum+=c.probability[head,i,j];}for(int j=0;j<n;j++)c.probability[head,i,j]/=Mathf.Max(1e-8f,sum);for(int h=0;h<headWidth;h++){int index=start+h;for(int j=0;j<n;j++)c.output[i][index]+=c.probability[head,i,j]*c.v[j][index];}}}return c;
    }
    private static float[][] BackwardAttention(AttentionCache c,float[][] og,float[] qw,float[] kw,float[] vw,float[] qwg,float[] kwg,float[] vwg,float[] gammaGradient)
    {
        int n=c.input.Length;float[][] ig=Enumerable.Range(0,n).Select(_=>new float[Hidden]).ToArray(),qg=Enumerable.Range(0,n).Select(_=>new float[Hidden]).ToArray(),kg=Enumerable.Range(0,n).Select(_=>new float[Hidden]).ToArray(),vg=Enumerable.Range(0,n).Select(_=>new float[Hidden]).ToArray();float[,,] pg=new float[c.heads,n,n];
        for(int head=0;head<c.heads;head++){int start=AttentionHeadStart(head,c.heads),headWidth=AttentionHeadWidth(head,c.heads);for(int i=0;i<n;i++)for(int h=0;h<headWidth;h++){int index=start+h;float gradient=og[i][index];ig[i][index]+=gradient;for(int j=0;j<n;j++){pg[head,i,j]+=gradient*c.v[j][index];vg[j][index]+=gradient*c.probability[head,i,j];}}}
        for(int head=0;head<c.heads;head++){int start=AttentionHeadStart(head,c.heads),headWidth=AttentionHeadWidth(head,c.heads);float scale=1f/Mathf.Sqrt(headWidth);for(int i=0;i<n;i++){float mean=0f;for(int j=0;j<n;j++)mean+=pg[head,i,j]*c.probability[head,i,j];for(int j=0;j<n;j++){float scoreGradient=c.probability[head,i,j]*(pg[head,i,j]-mean)*scale;for(int h=0;h<headWidth;h++){int index=start+h;qg[i][index]+=scoreGradient*c.k[j][index];kg[j][index]+=scoreGradient*c.q[i][index];}}}}
        for(int i=0;i<n;i++){float[] ng=new float[Hidden];BackwardLinear(c.normalized[i].output,qg[i],qw,qwg,ng);BackwardLinear(c.normalized[i].output,kg[i],kw,kwg,ng);BackwardLinear(c.normalized[i].output,vg[i],vw,vwg,ng);float[] rg=BackwardRms(c.normalized[i],ng,gammaGradient);for(int h=0;h<Hidden;h++)ig[i][h]+=rg[h];}return ig;
    }
    private static CrossAttentionCache ForwardCrossAttention(float[][] queries,float[][] tokens,float[] qw,float[] kw,float[] vw,float[] gamma,int queryGammaOffset,int tokenGammaOffset,int heads)
    {
        int qn=queries.Length,n=tokens.Length;var c=new CrossAttentionCache{queries=queries,tokens=tokens,normalizedQueries=new RmsCache[qn],normalizedTokens=new RmsCache[n],q=new float[qn][],k=new float[n][],v=new float[n][],output=new float[qn][],probability=new float[heads,qn,n],heads=heads};for(int i=0;i<qn;i++){c.normalizedQueries[i]=ForwardRms(queries[i],gamma,queryGammaOffset);c.q[i]=Linear(c.normalizedQueries[i].output,qw);c.output[i]=(float[])queries[i].Clone();}for(int j=0;j<n;j++){c.normalizedTokens[j]=ForwardRms(tokens[j],gamma,tokenGammaOffset);c.k[j]=Linear(c.normalizedTokens[j].output,kw);c.v[j]=Linear(c.normalizedTokens[j].output,vw);}int hw=Hidden/heads;float[] scores=new float[n];for(int head=0;head<heads;head++){int start=head*hw;float scale=1f/Mathf.Sqrt(hw);for(int i=0;i<qn;i++){float max=float.NegativeInfinity,sum=0f;for(int j=0;j<n;j++){float dot=0f;for(int h=0;h<hw;h++)dot+=c.q[i][start+h]*c.k[j][start+h];scores[j]=dot*scale;max=Mathf.Max(max,scores[j]);}for(int j=0;j<n;j++){float p=Mathf.Exp(Mathf.Clamp(scores[j]-max,-20f,20f));c.probability[head,i,j]=p;sum+=p;}for(int j=0;j<n;j++)c.probability[head,i,j]/=Mathf.Max(1e-8f,sum);for(int h=0;h<hw;h++)for(int j=0;j<n;j++)c.output[i][start+h]+=c.probability[head,i,j]*c.v[j][start+h];}}return c;
    }
    private static CrossBackward BackwardCrossAttention(CrossAttentionCache c,float[][] og,float[] qw,float[] kw,float[] vw,float[] qwg,float[] kwg,float[] vwg,float[] gammaGradient)
    {
        int qn=c.queries.Length,n=c.tokens.Length,hw=Hidden/c.heads;float[][] qig=Enumerable.Range(0,qn).Select(_=>new float[Hidden]).ToArray(),tig=Enumerable.Range(0,n).Select(_=>new float[Hidden]).ToArray(),qg=Enumerable.Range(0,qn).Select(_=>new float[Hidden]).ToArray(),kg=Enumerable.Range(0,n).Select(_=>new float[Hidden]).ToArray(),vg=Enumerable.Range(0,n).Select(_=>new float[Hidden]).ToArray();float[,,] pg=new float[c.heads,qn,n];for(int i=0;i<qn;i++)Array.Copy(og[i],qig[i],Hidden);for(int head=0;head<c.heads;head++){int start=head*hw;for(int i=0;i<qn;i++)for(int h=0;h<hw;h++){int x=start+h;for(int j=0;j<n;j++){pg[head,i,j]+=og[i][x]*c.v[j][x];vg[j][x]+=og[i][x]*c.probability[head,i,j];}}}for(int head=0;head<c.heads;head++){int start=head*hw;float scale=1f/Mathf.Sqrt(hw);for(int i=0;i<qn;i++){float mean=0f;for(int j=0;j<n;j++)mean+=pg[head,i,j]*c.probability[head,i,j];for(int j=0;j<n;j++){float sg=c.probability[head,i,j]*(pg[head,i,j]-mean)*scale;for(int h=0;h<hw;h++){int x=start+h;qg[i][x]+=sg*c.k[j][x];kg[j][x]+=sg*c.q[i][x];}}}}for(int i=0;i<qn;i++){float[] normalizedGradient=new float[Hidden];BackwardLinear(c.normalizedQueries[i].output,qg[i],qw,qwg,normalizedGradient);float[] rmsGradient=BackwardRms(c.normalizedQueries[i],normalizedGradient,gammaGradient);for(int h=0;h<Hidden;h++)qig[i][h]+=rmsGradient[h];}for(int j=0;j<n;j++){float[] normalizedGradient=new float[Hidden];BackwardLinear(c.normalizedTokens[j].output,kg[j],kw,kwg,normalizedGradient);BackwardLinear(c.normalizedTokens[j].output,vg[j],vw,vwg,normalizedGradient);tig[j]=BackwardRms(c.normalizedTokens[j],normalizedGradient,gammaGradient);}return new CrossBackward{queryGradient=qig,tokenGradient=tig};
    }

    private static MlpCache ForwardMlp(float[] input,float[] fw,float[] rw,float[][] deep,float[] bias,float[] norm,int normOffset)
    {
        var c=new MlpCache{fusion=ForwardDense(input,fw,bias,Hidden*2,Hidden*2,Hidden,true),norms=new RmsCache[deep.Length+1]};c.norms[0]=ForwardRms(c.fusion.output,norm,normOffset);c.residual=ForwardDense(c.norms[0].output,rw,bias,Hidden*3,Hidden,Hidden,true);c.merged=new float[Hidden];for(int h=0;h<Hidden;h++)c.merged[h]=c.fusion.output[h]+c.residual.output[h];c.deepLayers=new DenseCache[deep.Length];float[] current=c.merged;for(int i=0;i<deep.Length;i++){c.norms[i+1]=ForwardRms(current,norm,normOffset+Hidden*(i+1));c.deepLayers[i]=ForwardDense(c.norms[i+1].output,deep[i],bias,Hidden*(4+i),Hidden,Hidden,true);float[] next=new float[Hidden];for(int h=0;h<Hidden;h++)next[h]=current[h]+c.deepLayers[i].output[h];current=next;}c.output=current;return c;
    }
    private static float[] BackwardMlp(MlpCache c,float[] og,float[] fw,float[] rw,float[][] deep,float[] fwg,float[] rwg,float[][] deepg,float[] bg,float[] normGradient)
    {
        float[] gradient=(float[])og.Clone();for(int i=c.deepLayers.Length-1;i>=0;i--){float[] normalized=BackwardDense(c.deepLayers[i],gradient,deep[i],deepg?[i],bg);float[] extra=BackwardRms(c.norms[i+1],normalized,normGradient);for(int h=0;h<Hidden;h++)gradient[h]+=extra[h];}float[] fusionGradient=(float[])gradient.Clone();float[] residualNormalized=BackwardDense(c.residual,gradient,rw,rwg,bg);float[] residualInput=BackwardRms(c.norms[0],residualNormalized,normGradient);for(int h=0;h<Hidden;h++)fusionGradient[h]+=residualInput[h];return BackwardDense(c.fusion,fusionGradient,fw,fwg,bg);
    }

    private static RmsCache ForwardRms(float[] input,float[] gamma,int offset){float mean=0f;for(int i=0;i<Hidden;i++)mean+=input[i]*input[i]/Hidden;float inv=1f/Mathf.Sqrt(mean+RmsNormEpsilon);float[] output=new float[Hidden],used=new float[Hidden];for(int i=0;i<Hidden;i++){used[i]=gamma[offset+i];output[i]=input[i]*used[i]*inv;}return new RmsCache{input=input,output=output,gamma=used,gammaOffset=offset,inverse=inv};}
    private static float[] BackwardRms(RmsCache c,float[] og,float[] gammaGradient){float dot=0f;for(int i=0;i<Hidden;i++){dot+=og[i]*c.gamma[i]*c.input[i];if(gammaGradient!=null)gammaGradient[c.gammaOffset+i]+=og[i]*c.input[i]*c.inverse;}float correction=c.inverse*c.inverse*c.inverse*dot/Hidden;float[] ig=new float[Hidden];for(int i=0;i<Hidden;i++)ig[i]=og[i]*c.gamma[i]*c.inverse-c.input[i]*correction;return ig;}
    private static HeadCache ForwardHead(float[] input,float[] fw,float[] rw,float[][] deep,float[] ow,float[] bias,int outputCount,float scale){var c=new HeadCache{fusion=ForwardDense(input,fw,bias,Hidden*2,Hidden*2,Hidden,true),outputScale=scale};c.residual=ForwardDense(c.fusion.output,rw,bias,Hidden*3,Hidden,Hidden,true);c.merged=new float[Hidden];for(int h=0;h<Hidden;h++)c.merged[h]=(float)Math.Tanh(c.fusion.output[h]+c.residual.output[h]);c.deepLayers=new DenseCache[deep.Length];float[] current=c.merged;for(int i=0;i<deep.Length;i++){c.deepLayers[i]=ForwardDense(current,deep[i],bias,Hidden*(4+i),Hidden,Hidden,true);current=c.deepLayers[i].output;}c.outputLayer=ForwardDense(current,ow,bias,Hidden*(4+deep.Length),Hidden,outputCount,false);c.output=new float[outputCount];for(int i=0;i<outputCount;i++)c.output[i]=(float)Math.Tanh(c.outputLayer.pre[i])*scale;return c;}
    private static float[] BackwardHead(HeadCache c,float[] og,float[] fw,float[] rw,float[][] deep,float[] ow,float[] fwg,float[] rwg,float[][] deepg,float[] owg,float[] bg){float[] pg=new float[og.Length];for(int i=0;i<og.Length;i++){float t=c.output[i]/c.outputScale;pg[i]=og[i]*c.outputScale*(1f-t*t);}float[] mg=BackwardDense(c.outputLayer,pg,ow,owg,bg);for(int i=c.deepLayers.Length-1;i>=0;i--)mg=BackwardDense(c.deepLayers[i],mg,deep[i],deepg[i],bg);float[] fg=new float[Hidden],rg=new float[Hidden];for(int h=0;h<Hidden;h++){float gradient=mg[h]*(1f-c.merged[h]*c.merged[h]);fg[h]=gradient;rg[h]=gradient;}float[] extra=BackwardDense(c.residual,rg,rw,rwg,bg);for(int h=0;h<Hidden;h++)fg[h]+=extra[h];return BackwardDense(c.fusion,fg,fw,fwg,bg);}
    private static DenseCache ForwardDense(float[] input,float[] weights,float[] bias,int offset,int inputCount,int outputCount,bool activate){var c=new DenseCache{input=input,pre=new float[outputCount],output=new float[outputCount],biasOffset=offset,activate=activate};for(int o=0;o<outputCount;o++){float v=bias[offset+o];for(int i=0;i<inputCount;i++)v+=input[i]*weights[i*outputCount+o];c.pre[o]=v;c.output[o]=activate?SiLU(v):v;}return c;}
    private static float[] BackwardDense(DenseCache c,float[] og,float[] weights,float[] wg,float[] bg){int outputs=og.Length;float[] ig=new float[c.input.Length];for(int o=0;o<outputs;o++){float g=og[o]*(c.activate?SiLUDerivative(c.pre[o]):1f);if(bg!=null)bg[c.biasOffset+o]+=g;for(int i=0;i<c.input.Length;i++){if(wg!=null)wg[i*outputs+o]+=c.input[i]*g;ig[i]+=weights[i*outputs+o]*g;}}return ig;}
    private static Dictionary<string,float[]> Zero(IEnumerable<KeyValuePair<string,float[]>> parameters){var g=new Dictionary<string,float[]>();foreach(var p in parameters)g[p.Key]=new float[p.Value.Length];return g;}
    private static void ApplyAdam(IEnumerable<KeyValuePair<string,float[]>> parameters,Dictionary<string,float[]> gradients,NativeOptimizerState optimizer,float learningRate){float norm2=gradients.Values.Sum(a=>a.Sum(v=>v*v)),clip=1f/Mathf.Max(1f,Mathf.Sqrt(norm2));optimizer.step++;foreach(var p in parameters){var slot=optimizer.Get(p.Key,p.Value.Length);float[] g=gradients[p.Key];for(int i=0;i<p.Value.Length;i++){float v=g[i]*clip;slot.first[i]=.9f*slot.first[i]+.1f*v;slot.second[i]=.999f*slot.second[i]+.001f*v*v;float mh=slot.first[i]/(1f-Mathf.Pow(.9f,optimizer.step)),vh=slot.second[i]/(1f-Mathf.Pow(.999f,optimizer.step));p.Value[i]-=learningRate*mh/(Mathf.Sqrt(vh)+1e-8f);}}}
    private static float[] Linear(float[] input,float[] weights){float[] o=new float[Hidden];for(int i=0;i<Hidden;i++)for(int h=0;h<Hidden;h++)o[h]+=input[i]*weights[i*Hidden+h];return o;}
    private static int AttentionHeadStart(int head,int heads)=>head*Hidden/heads;
    private static int AttentionHeadWidth(int head,int heads)=>(head+1)*Hidden/heads-AttentionHeadStart(head,heads);
    private static void BackwardLinear(float[] input,float[] og,float[] weights,float[] wg,float[] ig){for(int i=0;i<Hidden;i++)for(int h=0;h<Hidden;h++){if(wg!=null)wg[i*Hidden+h]+=input[i]*og[h];ig[i]+=weights[i*Hidden+h]*og[h];}}
    public static float SiLU(float value)=>value*Sigmoid(value);
    public static float SiLUDerivative(float value){float s=Sigmoid(value);return s+value*s*(1f-s);}
    public static float[] RmsNormForTesting(float[] input,float[] gamma){int n=input.Length;float mean=0f;for(int i=0;i<n;i++)mean+=input[i]*input[i]/n;float inv=1f/Mathf.Sqrt(mean+RmsNormEpsilon);float[] output=new float[n];for(int i=0;i<n;i++)output[i]=input[i]*gamma[i]*inv;return output;}
    public static float[] RmsNormInputGradientForTesting(float[] input,float[] gamma,float[] upstream){int n=input.Length;float mean=0f,dot=0f;for(int i=0;i<n;i++){mean+=input[i]*input[i]/n;dot+=upstream[i]*gamma[i]*input[i];}float inv=1f/Mathf.Sqrt(mean+RmsNormEpsilon),correction=inv*inv*inv*dot/n;float[] gradient=new float[n];for(int i=0;i<n;i++)gradient[i]=upstream[i]*gamma[i]*inv-input[i]*correction;return gradient;}
    private static float Sigmoid(float value){value=Mathf.Clamp(value,-30f,30f);return 1f/(1f+Mathf.Exp(-value));}
    private static float[] G(Dictionary<string,float[]> gradients,string name)=>gradients==null?null:gradients[name];
    private static float Dot(float[] a,float[] b){float v=0f;for(int i=0;i<a.Length;i++)v+=a[i]*b[i];return v;}
    private static float[] Slice(float[] a,int start,int count){float[] r=new float[count];Array.Copy(a,start,r,0,count);return r;}
    private static float[] Concat(float[] a,float[] b){float[] r=new float[a.Length+b.Length];Array.Copy(a,r,a.Length);Array.Copy(b,0,r,a.Length,b.Length);return r;}
    private static float[] MeanTokens(float[][] tokens){float[] r=new float[Hidden];if(tokens.Length==0)return r;foreach(float[] t in tokens)for(int h=0;h<Hidden;h++)r[h]+=t[h]/tokens.Length;return r;}
}

